contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        address ownerBefore = c.Owner();
        uint cBalanceBefore = address(c).balance;
        uint ownerBalanceBefore = ownerBefore.balance;
        bool reverted;
        try c.withdraw{value: amount}() { reverted = false; } catch { reverted = true; }
        if (ownerBefore == address(this)) {
            assert(!reverted && address(c).balance == 0 && ownerBefore.balance == ownerBalanceBefore + cBalanceBefore + amount);
        } else {
            assert(reverted && address(c).balance == cBalanceBefore + amount);
        }
    }
    receive() external payable {}
}

