contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        // Snapshot the balance observable through the public surface before the call.
        uint balBefore = address(c).balance;

        bool reverted;
        try c.withdraw() { reverted = false; } catch { reverted = true; }

        // The owner is read from the public getter; the test contract deployed c,
