}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address adr, bytes memory data, uint amount) public payable {
        address owner = c.Owner();
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;
        require(beforeThis >= amount);
        bool reverted;
        try c.Command{value: amount}(adr, data) { reverted = false; } catch { reverted = true; }
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;
        if (msg.sender != owner) {
            assert(reverted);
        } else {
            if (amount > beforeC) {
                assert(reverted);
            } else {
                assert(!reverted && afterC <= beforeC && afterThis >= beforeThis);
            }
        }
    }

    receive() external payable {}
}

